<div class="table-responsive"><table class="table align-middle"><thead><tr><th>Kode</th><th>Pelanggan</th><th>Motor</th><th>Layanan</th><th>Tanggal</th><th>Status</th></tr></thead><tbody><?php foreach(array_slice($allBookings,0,10) as $b): ?><tr><td><b><?=e($b['booking_code'])?></b></td><td><?=e($b['customer_name'])?></td><td><?=e($b['motorcycle'])?></td><td><?=e($b['service_name'])?></td><td><?=date('d/m/Y',strtotime($b['booking_date']))?></td><td><span class="status-badge"><?=e($b['status'])?></span></td></tr><?php endforeach; ?><?php if(!$allBookings): ?><tr><td colspan="6" class="text-center py-4 muted">Belum ada booking.</td></tr><?php endif; ?></tbody></table></div>
